import AVFoundation

extension Exporter {

    /// Why an export stopped. Every case is reported through `completion` —
    /// nothing here throws at the caller and nothing crashes.
    enum ExportError: LocalizedError {
        /// The core could not produce a composition plan for this project.
        case noPlan
        /// Nothing to write: no video and no audio track in the plan. Reached
        /// by an empty timeline AND by one holding only text, shapes and
        /// images, which need no composition track (spec §7.2) — so the
        /// message has to name the second case, which is the surprising one.
        case emptyTimeline
        /// This Mac will not encode what the core's preset resolved to — an
        /// unknown codec name, one `AVAssetWriter` refuses an input for, or
        /// one whose encoder is not found when the write starts
        /// (`Exporter.encoderOutcome`). Carries the preset id when the core
        /// gave one, else the codec.
        case presetUnavailable(String)
        /// The settings named a container this build cannot map to a file
        /// type.
        case fileTypeUnsupported(String)
        /// An alpha-carrying row was asked for a size of a different SHAPE
        /// from the canvas, which cannot be written correctly and so is not
        /// written at all (road map 2, phase 7b). Carries the canvas and the
        /// size the core resolved, in that order.
        ///
        /// **Which sizes reach it** (spec §11 G-33 (c)): on `prores_4444` and
        /// `hevc_alpha`, a frame more than a pixel off the canvas's shape
        /// (`ExportWriter.shapeGap`: `gap > limit`). A frame within a pixel is
        /// filled instead of padded and is written — the evened Document row
        /// on a canvas with an odd edge, a standard row whose long edge
        /// rounded, a size typed in the canvas's own proportions (evened
        /// first on `hevc_alpha`, so an odd one is written a pixel smaller),
        /// and on `prores_4444` a typed frame one pixel short. So no size of
        /// the canvas's shape is refused for being odd; a typed size of any
        /// other shape is judged as the even frame it becomes
        /// (1279 × 720 on 1920 × 1080 is 1278 × 720 on `hevc_alpha`, and
        /// refused).
        ///
        /// **Measured, not feared.** `AVVideoScalingModeResizeAspect` pads
        /// the frame to the asked-for shape, and the padding path destroys
        /// the alpha channel: a 320 × 180 transparent canvas written
        /// `prores_4444` at 240 × 240 comes back with the PICTURE at alpha 0
        /// and the letterbox BARS at alpha 255 — the answer inverted, not
        /// merely lost. The same canvas at 160 × 90 or 640 × 360 is correct
        /// at every pixel, so the fault is the padding and nothing else.
        ///
        /// It is refused rather than documented because the file would be
        /// silently wrong in the one respect the row exists for, and this
        /// codebase's rule for exactly that shape is `codecType(for:)`'s:
        /// a refusal, never a fallback that puts a file on disk which is not
        /// the one asked for. Nothing legitimate is blocked by accident —
        /// every row of the Size popup is fitted to the document's own
        /// aspect (`export_size.rs`), so only a hand-typed Custom size of
        /// another shape can reach this (or a canvas, or a typed size, with
        /// an edge of exactly 1 px, raised to 2 on `hevc_alpha`), and the
        /// message says what to type instead: every size with the canvas's
        /// proportions is written, odd or even, smaller or larger.
        case alphaAspectMismatch(width: Int, height: Int, wantWidth: Int, wantHeight: Int)
        /// The user pressed Cancel. The sheet dismisses without an alert.
        case cancelled
        /// The write ended in a state that is neither completed nor
        /// cancelled and had no error of its own — or one of the reader's or
        /// writer's own steps refused with a message worth showing.
        case failed(String)
        /// Graphic clips in the range whose module does not compile, or is
        /// not in `graphics/`, each with what is wrong: the export was refused
        /// before it started (G-8). Sorted by name.
        case graphicsNotCompiled([(name: String, message: String)])
        /// A graphic failed while the export drew it, at its own frame — nil
        /// when it did not compile. The export stopped and its file is gone.
        case graphicFailed(name: String, frame: Int?, message: String)
        /// A ramped clip's audio render failed (spec §11 SR-12 (g), (h)): the
        /// export waits for every ramp segment it plays and never writes one
        /// silent, so it stops, naming the clip and the renderer's reason.
        case rampAudioFailed(clip: UInt32, message: String)
        /// A clip's isolated voice (spec §11 AU-57) could not be rendered: the
        /// export waits for it as for a ramp, and stops naming the clip.
        case isolationFailed(clip: UInt32, message: String)
        /// A gated or de-essed clip's loudness was still not measured when the
        /// export's wait ran out (spec §11 AU-42): its thresholds are relative
        /// to it, so the export stops naming the clip rather than writing it
        /// ungated.
        case loudnessUnmeasured(clip: UInt32)
        /// A clip's voice effect (spec §11 AU-147) could not be rendered: the
        /// export waits for it as for its isolation, and stops naming the clip.
        case voiceFailed(clip: UInt32, message: String)
        /// A cut-out clip's person masks (spec §11 CO-6, CO-22 (e)), or a
        /// picture's foreground masks (`foreground`, CO-106), could not be made:
        /// the export waits for every mask it draws, a picture's too, and stops
        /// naming the clip rather than writing it uncut.
        case cutoutFailed(clip: UInt32, message: String, foreground: Bool = false)

        var errorDescription: String? {
            switch self {
            case .noPlan:
                return "The project could not be prepared for export."
            case .emptyTimeline:
                return "There is nothing on the timeline to export — add a clip first."
            case .presetUnavailable(let name):
                return "This Mac cannot export with the “\(name)” preset."
            case .fileTypeUnsupported(let container):
                return "“\(container)” is not a container this build can write."
            case .alphaAspectMismatch(let width, let height, let wantWidth, let wantHeight):
                return "An export that keeps transparency has to have the canvas's own shape. "
                    + "This canvas is \(width) × \(height) and \(wantWidth) × \(wantHeight) is a "
                    + "different shape, so the picture would be padded and the padding loses the "
                    + "alpha channel. Export at \(width) × \(height), at one of the sizes in the "
                    + "popup, or at any size with the same proportions."
            case .cancelled:
                return "The export was cancelled."
            case .failed(let message):
                return message
            case .graphicsNotCompiled(let refused):
                let clauses = refused.map { "the graphic \"\($0.name)\" \($0.message)" }
                return "The export was not started: " + clauses.joined(separator: "; ")
                    + ". Fix the module and export again."
            case .graphicFailed(let name, let frame?, let message):
                return "The export was stopped at frame \(frame) of the graphic \"\(name)\": "
                    + "\(message). No file was written."
            case .graphicFailed(let name, nil, let message):
                return "The export was stopped: the graphic \"\(name)\" does not compile — "
                    + "\(message). No file was written."
            case .rampAudioFailed(let clip, let message):
                return "Clip \(clip)'s retimed audio could not be rendered: \(message)."
            case .isolationFailed(let clip, let message):
                return "Clip \(clip)'s isolated voice could not be rendered: \(message)."
            case .loudnessUnmeasured(let clip):
                return "Clip \(clip)'s loudness or speech has not been measured yet, so its "
                    + "gate, leveller and de-esser cannot be set. Wait for their Status rows to "
                    + "show the clip's loudness, then export again."
            case .voiceFailed(let clip, let message):
                return "Clip \(clip)'s voice effect could not be rendered: \(message)."
            case .cutoutFailed(let clip, let message, let foreground):
                return "Clip \(clip)'s \(foreground ? "foreground" : "person") masks could not be "
                    + "made: \(message)."
            }
        }
    }

    /// What a finished write becomes when the reason it failed is that this
    /// Mac has no encoder for the row (spec §11 G-33 (e)): the preset's own
    /// sentence, and no file.
    ///
    /// `ExportWriter.addVideo` cannot see it. Measured with an encoder
    /// specification nothing satisfies, on `.hevcWithAlpha` and `.hevc`
    /// alike: `canApply` is true, the input constructs, `canAdd` is true, and
    /// `startWriting()` then fails with `AVFoundationErrorDomain` −11834
    /// ("Cannot Encode"), leaving a 0-byte file at the destination. So it is
    /// mapped here, where `startWriting` hears the pipeline: exactly that
    /// domain and code become `.presetUnavailable` with the preset's name and
    /// the file is removed, and every other result is returned as it came.
    static func encoderOutcome(
        _ result: Result<URL, any Error>, settings: ExportSettings, destination: URL
    ) -> Result<URL, any Error> {
        guard case .failure(let error) = result else { return result }
        let reason = error as NSError
        guard reason.domain == AVFoundationErrorDomain,
            reason.code == AVError.Code.encoderNotFound.rawValue
        else { return result }
        try? FileManager.default.removeItem(at: destination)
        return .failure(ExportError.presetUnavailable(ExportWriter.presetName(settings)))
    }
}
import Foundation

// The arithmetic that turns a loudness measurement into an export gain: a pure move out of
// `Loudness.swift` (road map "audio" AP0's toll T3), which keeps the BS.1770-4 meter and the
// `LoudnessReport` it answers.

// MARK: - What an export did about it

/// A measurement, the target it was measured against, and the gain that
/// follows — the value both consumers of an export read (the progress
/// sheet's final line and the `export` tool's result).
///
/// **The gain is applied under a master limiter** (spec §11 AU-27, AU-28):
/// every export with sound runs `ExportAudioMaster` — the gain, then
/// `AudioLimiterStage` at the export's ceiling — so the gain that reaches a
/// target is solved through `AudioLimiterModel` over pass one's 10 ms steps,
/// the model the clip limiter's Normalize already uses (AU-24). A scalar gain
/// shifts the true peak by itself, and the master holds what passes the
/// ceiling there, so the file's true peak is `min(measured + gain, ceiling)`
/// and what the master took off is `limitedDB`. Nothing clips any more.
///
/// This file stays free of AVFoundation and AppKit: `phase5_chrome.py` §9
/// compiles it with `Loudness.swift`, `StepLoudness.swift` and
/// `AudioLimiterModel.swift` alone.
struct ExportLoudness: Equatable {
    /// What the mix measured, before any gain.
    let measured: LoudnessReport
    /// The integrated target that was asked for, or nil when the export was
    /// not normalised at all and this is a readout.
    let target: Double?
    /// The master limiter's true-peak ceiling, dBTP.
    let ceiling: Double
    /// The gain that was applied, in dB. Quantised (see `gainStepDB`), and
    /// exactly 0 when nothing was applied.
    let gainDB: Double
    /// What the file holds, LUFS: the model's figure at `gainDB` under the
    /// master (AU-28), else the measurement shifted by the gain; nil when
    /// gated out.
    let integratedLUFS: Double?
    /// True when the +40 dB cap, not the target, decided the gain — the case
    /// worth reporting, because the file will then be quieter than asked.
    let cappedByGain: Bool

    /// The master's ceiling when a caller names none: AU-4's −1 dBTP, for
    /// normalised and un-normalised exports alike (AU-27).
    static let defaultCeiling: Double = -1

    /// The most gain a target may ask for, dB.
    static let maxGainDB: Double = 40

    /// The master limiter's release, seconds (AU-27): `ExportAudioMaster`'s,
    /// spelled here so the model and the stage read one number.
    static let masterReleaseSeconds = 0.1

    /// The fewest 10 ms steps the model is run over: one 400 ms gating block.
    private static let modelSteps = 40

    /// The grid the applied gain is rounded to, in dB — to NEAREST (AU-28):
    /// the limiter holds the ceiling, so no rounding has to lean toward it.
    ///
    /// Not cosmetic. AVFoundation's mix is not bit-deterministic near a duck
    /// ramp edge (CLAUDE.md records 38 samples of one 16-bit LSB), which
    /// moves the measured loudness by something like 10⁻⁵ LU — irrelevant to
    /// a ±0.5 LU target, but enough that a raw `Double` gain would differ in
    /// its last bits between two runs and round the ENTIRE file's samples
    /// differently. At 0.01 dB the two runs pick the same gain, so two
    /// normalised exports of one project compare, and "−14.0 LUFS"
    /// reproduces.
    static let gainStepDB: Double = 0.01

    /// The linear multiplier the master applies to the float mix.
    var linearGain: Double { pow(10, gainDB / 20) }

    /// True when the master has no gain to apply. It still limits and
    /// quantises.
    var isUnity: Bool { gainDB == 0 }

    /// The file's true peak: the measurement shifted by the gain, held at the
    /// ceiling. A non-finite measurement passes through unclamped, so the
    /// summary can still say "Silent" (−∞) or that the peak could not be
    /// measured (+∞).
    var truePeakDBTP: Double {
        guard measured.truePeakDBTP.isFinite else { return measured.truePeakDBTP }
        return min(measured.truePeakDBTP + gainDB, ceiling)
    }

    /// How far the master turned the hottest peak down, dB: the shifted
    /// measurement's excess over the ceiling, 0 when under it or not finite.
    var limitedDB: Double {
        guard measured.truePeakDBTP.isFinite else { return 0 }
        return max(0, measured.truePeakDBTP + gainDB - ceiling)
    }

    /// The gain a `target` asks for over `measured` and its 10 ms `steps`
    /// (energies) and `peaks` (true peaks, linear) under the master's
    /// `ceiling` (spec §11 AU-28).
    ///
    /// `target` nil is "do not normalise": the measurement is still carried,
    /// and the file's loudness is still the model's, because the master
    /// limits an un-normalised mix that passes the ceiling too.
    ///
    /// A peak that is not a finite number keeps the old handling: no model,
    /// no gain, the measured loudness. −∞ is digital silence; +∞ is float
    /// source media holding a non-finite sample, and "the peak cannot be
    /// measured" has to mean "do not push it up".
    static func resolve(
        measured: LoudnessReport, steps: [Double], peaks: [Double], target: Double?,
        ceiling: Double?
    ) -> ExportLoudness {
        let ceiling = ceiling ?? defaultCeiling
        guard measured.truePeakDBTP.isFinite else {
            return ExportLoudness(
                measured: measured, target: target, ceiling: ceiling, gainDB: 0,
                integratedLUFS: measured.integratedLUFS, cappedByGain: false)
        }
        let linearCeiling = pow(10, ceiling / 20)
        let modelled = steps.count >= modelSteps && StepLoudness.integrated(steps) != nil
        var gainDB = 0.0
        var capped = false
        if let target, let integrated = measured.integratedLUFS {
            let wanted: Double
            if modelled {
                let maxGain = pow(10, maxGainDB / 20)
                let gain = AudioLimiterModel.gain(
                    reaching: target, steps: steps, peaks: peaks, ceiling: linearCeiling,
                    releaseSeconds: masterReleaseSeconds, maxGain: maxGain)
                capped = gain >= maxGain
                wanted = 20 * log10(gain)
            } else {
                // Under one gating block, or no float read: the unlimited gain.
                wanted = target - integrated
                capped = wanted > maxGainDB
            }
            let rounded = min((wanted / gainStepDB).rounded() * gainStepDB, maxGainDB)
            gainDB = rounded.isFinite ? rounded : 0
        }
        let shifted = measured.integratedLUFS.map { $0 + gainDB }
        let lufs = modelled
            ? AudioLimiterModel.integrated(
                steps: steps, peaks: peaks, gain: pow(10, gainDB / 20), ceiling: linearCeiling,
                releaseSeconds: masterReleaseSeconds) ?? shifted
            : shifted
        return ExportLoudness(
            measured: measured, target: target, ceiling: ceiling, gainDB: gainDB,
            integratedLUFS: lufs, cappedByGain: capped)
    }

    /// The one line every export reports: `"Peak −1.0 dBTP · −16.0 LUFS"`, with
    /// `" · peaks limited by 8.6 dB"` when the master took 0.05 dB or more off.
    var summary: String {
        guard truePeakDBTP.isFinite else {
            // −∞ is digital silence. Anything else non-finite is a mix
            // carrying a non-finite sample, and calling THAT silent is the
            // loudest lie this line could tell.
            return truePeakDBTP == -.infinity
                ? "Silent" : "Peak not measurable (a non-finite sample in the mix)"
        }
        let peak = "Peak \(Self.decibels(truePeakDBTP)) dBTP"
        var measurement: String
        if let integrated = integratedLUFS {
            measurement = "\(peak) · \(Self.decibels(integrated)) LUFS"
        } else {
            // A programme shorter than one 400 ms gating block, or one whose
            // every block fell under Γa. It has a peak and no loudness, and
            // saying which is better than printing −∞.
            measurement = "\(peak) · loudness not measurable"
        }
        if limitedDB >= 0.05 {
            measurement += " · peaks limited by \(Self.decibels(limitedDB)) dB"
        }
        return measurement
    }

    /// One decimal, with the typographic minus the rest of the chrome uses.
    private static func decibels(_ value: Double) -> String {
        String(format: "%.1f", value).replacingOccurrences(of: "-", with: "−")
    }
}

import AppKit
import UniformTypeIdentifiers

final class ExportSheetController: NSViewController {
    weak var editor: EditorViewController?

    let presets: [ExportPreset]
    var sizes: [ExportSize] = []
    var visibleSizes: [ExportSize] = []
    private var sizesPreset: String?
    var sizesError: String?
    let range: (start: Ticks, end: Ticks)?

    private let rangeIsTheNests: Bool

    var userPresets = ExportPresetsStore.load()

    var resolved: ExportSettings?
    var resolveError: String?

    let presetPopup = NSPopUpButton(frame: .zero, pullsDown: false)
    let presetMenuButton = NSPopUpButton(frame: .zero, pullsDown: true)
    let burnInCheckbox = NSButton(
        checkboxWithTitle: "Burn in timecode", target: nil, action: nil)
    let formatPopup = NSPopUpButton(frame: .zero, pullsDown: false)
    let sizePopup = NSPopUpButton(frame: .zero, pullsDown: false)
    let widthField = NSTextField(string: "")
    let heightField = NSTextField(string: "")
    let ratePopup = NSPopUpButton(frame: .zero, pullsDown: false)
    let qualityPopup = NSPopUpButton(frame: .zero, pullsDown: false)
    let loudnessPopup = NSPopUpButton(frame: .zero, pullsDown: false)
    let loudnessField = NSTextField(string: "")
    let rangePopup = NSPopUpButton(frame: .zero, pullsDown: false)
    let dynamicRangePopup = NSPopUpButton(frame: .zero, pullsDown: false)
    var dynamicRangeChoice: DynamicRange = .hlg
    let speedPopup = NSPopUpButton(frame: .zero, pullsDown: false)
    var encoderSpeedChoice: EncoderSpeed = .balanced
    let audioBitsPopup = NSPopUpButton(frame: .zero, pullsDown: false)
    var audioBitsChoice = 16
    let stemsPopup = NSPopUpButton(frame: .zero, pullsDown: false)
    var stemsChoice: String?
    let summaryLabel = NSTextField(wrappingLabelWithString: "")
    let footnote = sheetFootnote("")
    var exportButton: NSButton!
    var queueButton: NSButton!

    static let rates: [Fps] = Fps.common
    static let cardWidth: CGFloat = sheetWidth + 60

    init(editor: EditorViewController) {
        self.editor = editor
        self.presets = ReelExport.presets()
        // `scope == nil` is the first half of the test, not an afterthought:
        // see the property's doc above and the rule at
        // `ProjectDocument.inOutRange`. A range set inside a nest is the
        // nest's, and this card writes the timeline.
        let bounds = editor.document?.inOutRange
        let live = bounds.map { $0.end > $0.start } ?? false
        let scoped = editor.document?.scope != nil
        self.range = live && !scoped ? bounds : nil
        self.rangeIsTheNests = live && scoped
        super.init(nibName: nil, bundle: nil)
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("ExportSheetController does not support NSCoder")
    }

    // MARK: - View

    override func loadView() {
        formatPopup.addItems(withTitles: presets.map { $0.name })
        // The sheet opens on the first row of each of the core's two lists:
        // the H.264 format (`export.rs`, `PRESETS`) and, in its Size popup,
        // the document's own size (`export_size.rs`), so that ⌘E exports the
        // document as it is unless a person picks otherwise. Each default
        // has one home — the order of its list — and this is only the
        // reading of it, made explicit, and guarded so that an empty table
        // reaches `resolve()`'s own message rather than a selection out of
        // range.
        if !presets.isEmpty { formatPopup.selectItem(at: 0) }
        formatPopup.font = DS.sans(13)
        formatPopup.target = self
        formatPopup.action = #selector(formatChanged(_:))
        formatPopup.widthAnchor.constraint(equalToConstant: 240).isActive = true

        sizePopup.font = DS.sans(13)
        sizePopup.target = self
        sizePopup.action = #selector(sizeChanged(_:))
        sizePopup.widthAnchor.constraint(equalToConstant: 240).isActive = true

        for field in [widthField, heightField] {
            let formatter = NumberFormatter()
            formatter.numberStyle = .none
            formatter.allowsFloats = false
            formatter.minimum = NSNumber(value: Self.sizeRange.lowerBound)
            formatter.maximum = NSNumber(value: Self.sizeRange.upperBound)
            field.formatter = formatter
            field.delegate = self
            field.alignment = .right
            field.widthAnchor.constraint(equalToConstant: 72).isActive = true
            DSField.style(field)
        }

        ratePopup.addItem(withTitle: "Project rate")
        ratePopup.addItems(withTitles: Self.rates.map { "\($0.displayName) fps" })
        ratePopup.font = DS.sans(13)
        ratePopup.target = self
        ratePopup.action = #selector(rangeOrRateChanged(_:))
        ratePopup.widthAnchor.constraint(equalToConstant: 150).isActive = true

        qualityPopup.addItem(withTitle: "Format default")
        // Bare names now; `syncQualityTitles` puts the rate each tier would
        // ask for beside them as soon as the first resolve has run.
        qualityPopup.addItems(withTitles: Self.tiers.map { $0.name })
        qualityPopup.font = DS.sans(13)
        qualityPopup.target = self
        qualityPopup.action = #selector(qualityChanged(_:))
        qualityPopup.widthAnchor.constraint(equalToConstant: 200).isActive = true

        loudnessPopup.addItem(withTitle: "Off")
        loudnessPopup.addItems(withTitles: Self.loudnessTargets.map { Self.loudnessTitle($0) })
        loudnessPopup.addItem(withTitle: "Custom…")
        loudnessPopup.font = DS.sans(13)
        loudnessPopup.target = self
        loudnessPopup.action = #selector(loudnessChanged(_:))
        loudnessPopup.widthAnchor.constraint(equalToConstant: 186).isActive = true

        let loudnessFormatter = NumberFormatter()
        loudnessFormatter.numberStyle = .decimal
        loudnessFormatter.allowsFloats = true
        loudnessFormatter.maximumFractionDigits = 1
        loudnessFormatter.minimum = NSNumber(value: Self.loudnessRange.lowerBound)
        loudnessFormatter.maximum = NSNumber(value: Self.loudnessRange.upperBound)
        loudnessField.formatter = loudnessFormatter
        loudnessField.delegate = self
        loudnessField.alignment = .right
        loudnessField.placeholderString = "LUFS"
        loudnessField.widthAnchor.constraint(equalToConstant: 64).isActive = true
        DSField.style(loudnessField)

        rangePopup.addItem(withTitle: "Whole project")
        if range != nil { rangePopup.addItem(withTitle: "In/out range") }
        rangePopup.font = DS.sans(13)
        rangePopup.target = self
        rangePopup.action = #selector(rangeOrRateChanged(_:))
        rangePopup.isEnabled = range != nil
        rangePopup.widthAnchor.constraint(equalToConstant: 150).isActive = true
        // A disabled Range popup ordinarily means "this document has no
        // range". Inside a nest it means something else — "the range there is
        // belongs to the nest you are editing inside" — and the two are the
        // same picture, so the one that would surprise somebody carries the
        // sentence. A tooltip rather than a row: an "In/out range" row that
        // refused the moment it was picked would be a control lying about
        // what it does, and the card's `hint` is one paragraph written for
        // every export rather than for this session's. The tooltip lands
        // because this is a stock `NSPopUpButton` — the app's dead-tooltip
        // pitfall is about custom controls that clear their own tracking
        // areas and take `NSToolTipManager`'s with them.
        if rangeIsTheNests {
            rangePopup.toolTip =
                "The in/out range belongs to the nest you are editing inside. An export "
                + "writes the whole timeline, so it cannot use it — leave the nest (⌘↑) "
                + "and set a range on the timeline."
        }

        burnInCheckbox.font = DS.sans(13)
        burnInCheckbox.target = self
        burnInCheckbox.action = #selector(burnInChanged(_:))

        presetPopup.font = DS.sans(13)
        presetPopup.target = self
        presetPopup.action = #selector(presetChanged(_:))
        presetPopup.widthAnchor.constraint(equalToConstant: 216).isActive = true
        buildPresetMenuButton()
        rebuildPresetPopup(selecting: nil)
        configureDynamicRange()
        configureSpeed()
        configureAudioBits()
        configureStems()

        // THE ORDER BELOW IS LOAD-BEARING and `apply(_:)` is where it is
        // written down. The remembered choice has to reach the format popup
        // BEFORE the sizes are listed and the size popup AFTER, because
        // `rebuildSizes()` lists for the format that is selected and then puts
        // the popup back on row 0 unconditionally. Nothing remembered takes
        // the path this sheet has always taken — the first format, the
        // format's default size — so a first run is byte for byte the card it
        // was before phase 7.
        if let remembered = ExportChoice.remembered {
            apply(remembered)
        } else {
            rebuildSizes()
        }

        summaryLabel.font = DS.mono(11)
        summaryLabel.textColor = DS.textMuted
        summaryLabel.preferredMaxLayoutWidth = Self.cardWidth - sheetInset * 2

        var rows: [[NSView]] = [
            // The Preset row is FIRST because it is the row that sets every
            // other one: reading down the card is then "this is the shape of
            // export I want" followed by what that shape means.
            [fieldLabel("Preset:"), presetRow()],
            [fieldLabel("Format:"), formatPopup],
            [fieldLabel("Size:"), sizePopup],
            // The custom fields get a row of their own under the popup: on the
            // 480-wide card a 240 popup fits beside its 106 label column and
            // the popup plus two fields does not.
            [
                NSGridCell.emptyContentView,
                sheetRow([widthField, sheetUnitLabel("×"), heightField]),
            ],
            [fieldLabel("Frame rate:"), ratePopup],
            [fieldLabel("Quality:"), qualityPopup],
            [fieldLabel("Bit depth:"), audioBitsPopup],
            [fieldLabel("Stems:"), stemsPopup],
            // ONE row, popup and field together: 186 + 6 + 64 fits the 318
            // points the 480-wide card leaves beside a 106 label column.
            [fieldLabel("Loudness:"), sheetRow([loudnessPopup, loudnessField])],
            [fieldLabel("Range:"), rangePopup],
            // No label: the checkbox carries its own, the way
            // `SpeedSheetController`'s "Preserve pitch" does.
            [NSGridCell.emptyContentView, burnInCheckbox],
        ]
        // Under Format, in an HLG project only (spec §11 HD-14 (h)).
        if isHLGProject {
            rows.insert([fieldLabel("Dynamic Range:"), dynamicRangePopup], at: 2)
        }
        rows.insert([fieldLabel("Speed:"), speedPopup], at: isHLGProject ? 3 : 2)
        let grid = makeSheetGrid(rows)

        // The readout and the footnote sit UNDER the grid, each on a line of
        // its own: from the grid's indented column the readout would run past
        // the card's edge, and beside the buttons a footnote with a bit rate is cut (#243).
        let content = sheetColumn([grid, summaryLabel, footnote])

        let cancelButton = sheetCancelButton(target: self, action: #selector(cancelClicked(_:)))
        exportButton = StickerButton(
            title: "Export…", style: .primary, target: self, action: #selector(exportClicked(_:)))
        queueButton = StickerButton(
            title: "Add to Queue", style: .secondary, target: self,
            action: #selector(queueClicked(_:)))
        view = makeSheetView(
            title: "Export",
            hint: "The format decides the codec and the container. Size, frame rate and "
                + "range start as the document's and quality as the format's; a GIF or an "
                + "APNG starts at its own cap and rate. Loudness normalises the whole mix "
                + "by one gain, and every export's sound goes through a master limiter "
                + "that keeps its true peak under −1 dBTP. A preset remembers the choices on this card rather than the "
                + "numbers they resolve to, so it means the same thing on a document of "
                + "another size. Burn in timecode writes the time into the picture on "
                + "export only — the preview never shows it — and it reads PROJECT time, "
                + "so a file written from an in/out range starting at 00:00:10:00 begins "
                + "at 00:00 with a burn-in reading 00:00:10:00, which is what a review "
                + "copy wants. Add to Queue writes the same file without the wait — the "
                + "job keeps this project as it is now and runs behind the editor, one at "
                + "a time, in Window ▸ Export Queue; an AV1 or VP9 job there also waits "
                + "while the app's other AV1 and VP9 exports would hold more than a quarter "
                + "of this Mac's memory with it.",
            content: content,
            buttonRow: makeButtonRow(
                cancel: cancelButton, apply: exportButton, secondary: queueButton),
            width: Self.cardWidth)

        resolveCard()
    }

    func resolveCard() {
        resolve()
        queueButton?.isEnabled = exportButton?.isEnabled ?? false
    }

    func rebuildSizes() {
        sizes = []
        sizesError = nil
        sizesPreset = currentPreset?.id
        if let project = editor?.document?.project, let preset = currentPreset {
            do {
                sizes = try ReelExport.sizes(project, preset: preset.id)
            } catch {
                sizesError = error.localizedDescription
            }
        }
        visibleSizes = sizes.reduce(into: []) { shown, row in
            if !shown.contains(where: { $0.width == row.width && $0.height == row.height }) {
                shown.append(row)
            }
        }
        sizePopup.removeAllItems()
        sizePopup.addItems(
            withTitles: visibleSizes.map { "\($0.name) · \($0.width) × \($0.height)" })
        sizePopup.addItem(withTitle: "Custom…")
        sizePopup.selectItem(at: 0)
    }

    // MARK: - Controls

    @objc private func formatChanged(_ sender: Any?) {
        guard currentPreset?.id != sizesPreset else { return }
        presetEdited()
        rebuildSizes()
        resolveCard()
    }

    @objc private func sizeChanged(_ sender: Any?) {
        presetEdited()
        resolveCard()
    }

    @objc private func rangeOrRateChanged(_ sender: Any?) {
        presetEdited()
        resolveCard()
    }

    @objc private func qualityChanged(_ sender: Any?) {
        presetEdited()
        resolveCard()
    }

    @objc private func loudnessChanged(_ sender: Any?) {
        presetEdited()
        resolveCard()
    }

    @objc private func burnInChanged(_ sender: Any?) {
        presetEdited()
    }
}

// MARK: - Size fields

extension ExportSheetController: NSTextFieldDelegate {
    func controlTextDidEndEditing(_ obj: Notification) {
        guard isCustomSize || isCustomLoudness else { return }
        presetEdited()
        resolveCard()
    }
